-- Fonte: BCB ParticipantesSTR.csv (https://www.bcb.gov.br/content/estabilidadefinanceira/str1/ParticipantesSTR.csv).
CREATE TABLE IF NOT EXISTS instituicoes_bancarias (
    codigo_banco VARCHAR(3) NOT NULL PRIMARY KEY,
    nome_banco VARCHAR(150) NOT NULL,
    criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

